def require_no_advisories(document):
    if document.get("version") != 1 or not document.get("projects") or set(document.get("sources", [])) != {NUGET_SOURCE}:
        raise RuntimeError("Vulnerability audit result is missing its projects or actual sources")
    for project in document["projects"]:
        for framework in project.get("frameworks", []):
            for group in ("topLevelPackages", "transitivePackages"):
                for package in framework.get(group, []):
                    if package.get("vulnerabilities"):
                        raise RuntimeError("NuGet reported a package vulnerability; preparation refused")
